:root {
  color-scheme: dark;
  --accent: #ffbb54;
  --space-bg: #080f25;
  --space-panel: #141f39;
  --space-text: #f4f7ff;
  --space-muted: #c4cee3;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  padding: clamp(12px, 4vw, 32px);
  background-color: var(--space-bg);
  background-image:
    radial-gradient(circle at 12% 18%, #ffffff80 1px, transparent 2px),
    radial-gradient(circle at 83% 32%, #ffffff65 1px, transparent 2px),
    radial-gradient(circle at 32% 82%, #ffffff55 1px, transparent 2px),
    radial-gradient(ellipse at 50% 0%, #253765 0%, transparent 65%);
  background-size: 137px 173px, 211px 229px, 263px 197px, 100% 100%;
  color: var(--space-text);
  font-family: system-ui, sans-serif;
  line-height: 1.65;
}

.space-timer {
  width: 100%;
  max-width: 640px;
  margin-inline: auto;
  overflow-wrap: anywhere;
}

.mission-header { text-align: center; margin-bottom: 24px; }
.mission-header > span { display: block; font-size: 2.5rem; }
h1 { margin: 8px 0; font-size: clamp(1.5rem, 5vw, 2rem); }
h2 { margin: 0 0 12px; font-size: 1.2rem; }
p { margin: 12px 0; }
.mission-header p, #timer-format { color: var(--space-muted); }

.timer-panel {
  padding: clamp(16px, 5vw, 32px);
  border: 1px solid #657594;
  border-top: 4px solid var(--accent);
  border-radius: 24px;
  background: var(--space-panel);
  box-shadow: 0 16px 40px #00000040;
  text-align: center;
}

#timer-format { margin-bottom: 8px; font-size: 0.95rem; }
.timer-display {
  margin: 8px 0;
  color: #ffffff;
  font-family: ui-monospace, monospace;
  font-size: clamp(2.5rem, 13vw, 5.5rem);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
  letter-spacing: 0.02em;
  overflow-wrap: anywhere;
}

.mission-status {
  min-height: 1.65em;
  margin: 16px 0 24px;
  font-size: 1.15rem;
  font-weight: 700;
}

.timer-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.timer-controls button {
  flex: 1 1 100px;
  min-width: 0;
  min-height: 48px;
  padding: 12px 18px;
  border: 2px solid #a2b2d0;
  border-radius: 12px;
  background: #263958;
  color: #ffffff;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  touch-action: manipulation;
}

#start-button {
  background: #f4f7ff;
  color: #101b30;
  border-color: #f4f7ff;
  box-shadow: inset 0 -4px 0 var(--accent);
}

@media (hover: hover) {
  .timer-controls button:not(:disabled):hover {
    background: #3b5278;
    border-color: #ffffff;
  }
  #start-button:not(:disabled):hover { background: #dce7ff; }
}

.timer-controls button:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 4px;
}

.timer-controls button:not(:disabled):active { transform: translateY(1px); }

.timer-controls button:disabled,
#start-button:disabled {
  background: #202b41;
  color: #aebbd2;
  border-color: #74829d;
  border-style: dashed;
  box-shadow: none;
  cursor: default;
}

.mission-progress { margin-top: 28px; text-align: left; }
.mission-progress label { display: block; margin-bottom: 8px; font-weight: 600; }
progress {
  display: block;
  width: 100%;
  height: 18px;
  overflow: hidden;
  border: 1px solid #a2b2d0;
  border-radius: 999px;
  background: #080f25;
  accent-color: var(--accent);
}
progress::-webkit-progress-bar { background: #080f25; }
progress::-webkit-progress-value {
  background: var(--accent);
  border-right: 2px solid #ffffff;
}
progress::-moz-progress-bar {
  background: var(--accent);
  border-right: 2px solid #ffffff;
}

#mission-encouragement { margin-top: 20px; color: var(--space-text); }
#mission-announcement { min-height: 1.65em; color: var(--space-muted); }

.mission-instructions {
  margin-top: 24px;
  padding: 20px;
  border: 1px solid #657594;
  border-radius: 16px;
  background: #101a30;
  color: var(--space-muted);
}
.mission-instructions h2 { color: var(--space-text); }
.mission-instructions p:last-child { margin-bottom: 0; }

@media (max-width: 320px) {
  .timer-controls { flex-direction: column; }
  .timer-controls button { flex: auto; width: 100%; }
  .timer-panel { padding: 16px 12px; }
}

@media (forced-colors: active) {
  .timer-panel, .mission-instructions { border: 2px solid CanvasText; }
  .timer-controls button:focus-visible { outline-color: Highlight; }
  .timer-controls button:disabled, #start-button:disabled {
    color: GrayText;
    border-color: GrayText;
  }
  progress { forced-color-adjust: auto; }
}

const config = window.SPROUT_CONFIG || {};
const minutes = config.durationMinutes;
const seconds = typeof minutes === 'number' ? Math.round(minutes * 60) : NaN;
const totalSeconds = Number.isFinite(minutes) && minutes > 0 && Number.isSafeInteger(seconds) && seconds > 0 ? seconds : 300;

const display = document.getElementById('timer-display');
const statusText = document.getElementById('mission-status');
const startButton = document.getElementById('start-button');
const pauseButton = document.getElementById('pause-button');
const resetButton = document.getElementById('reset-button');

let remainingSeconds = totalSeconds;
let status = 'idle';
let intervalId = null;
let successSent = false;
let generation = 0;

function getState() {
  return {
    totalSeconds,
    remainingSeconds,
    status,
    running: status === 'running',
    completed: status === 'completed',
    progress: (totalSeconds - remainingSeconds) / totalSeconds
  };
}

function render(action) {
  const minutesText = String(Math.floor(remainingSeconds / 60)).padStart(2, '0');
  const secondsText = String(remainingSeconds % 60).padStart(2, '0');
  display.textContent = `${minutesText}:${secondsText}`;
  statusText.textContent = {
    idle: '准备就绪',
    running: '任务进行中',
    paused: '已暂停',
    completed: '任务完成'
  }[status];
  startButton.disabled = status === 'running' || status === 'completed';
  pauseButton.disabled = status !== 'running';
  resetButton.disabled = false;
  window.dispatchEvent(new CustomEvent('sprout:timer-update', {
    detail: { ...getState(), action }
  }));
}

function stopClock() {
  generation += 1;
  if (intervalId !== null) {
    window.clearInterval(intervalId);
    intervalId = null;
  }
}

function start() {
  if (status === 'running' || remainingSeconds === 0) return;
  status = 'running';
  const currentGeneration = ++generation;
  intervalId = window.setInterval(() => {
    if (currentGeneration !== generation || status !== 'running') return;
    remainingSeconds = Math.max(0, remainingSeconds - 1);
    if (remainingSeconds === 0) {
      stopClock();
      status = 'completed';
      const shouldAnnounceSuccess = !successSent;
      successSent = true;
      const completedState = getState();
      render('complete');
      if (shouldAnnounceSuccess) {
        window.dispatchEvent(new CustomEvent('sprout:success', {
          detail: completedState
        }));
      }
    } else {
      render('tick');
    }
  }, 1000);
  render('start');
}

function pause() {
  if (status !== 'running') return;
  stopClock();
  status = 'paused';
  render('pause');
}

function reset() {
  stopClock();
  remainingSeconds = totalSeconds;
  status = 'idle';
  successSent = false;
  render('reset');
}

startButton.addEventListener('click', start);
pauseButton.addEventListener('click', pause);
resetButton.addEventListener('click', reset);

// 后续反馈模块可读取初始状态，并监听窗口上的状态更新事件。
window.SPROUT_TIMER = Object.freeze({ getState });
render('init');

(() => {
  const config = window.SPROUT_CONFIG || {};
  const petName = typeof config.petName === 'string' && config.petName.trim()
    ? config.petName.trim() : '芽芽';
  const accent = typeof config.accent === 'string' ? config.accent.trim() : '';
  if (/^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(accent)) {
    document.documentElement.style.setProperty('--accent', accent);
  }

  const progress = document.getElementById('mission-progress');
  const encouragement = document.getElementById('mission-encouragement');
  const announcement = document.getElementById('mission-announcement');
  const start = document.getElementById('start-button');
  const pause = document.getElementById('pause-button');
  const reset = document.getElementById('reset-button');

  progress.setAttribute('aria-label', '任务进度');
  progress.max = 100;
  announcement.setAttribute('role', 'status');
  announcement.setAttribute('aria-live', 'polite');
  announcement.setAttribute('aria-atomic', 'true');

  let previousStatus = null;

  function update(state, action) {
    if (!state) return;
    const completed = state.status === 'completed';
    const running = state.status === 'running';
    const fraction = Number.isFinite(state.progress)
      ? Math.max(0, Math.min(1, state.progress)) : 0;
    const percent = completed ? 100 : fraction * 100;
    progress.value = percent;
    progress.textContent = `${Math.floor(percent)}%`;
    progress.setAttribute('aria-valuetext', `已完成 ${Math.floor(percent)}%`);

    start.disabled = running || completed;
    pause.disabled = !running;
    reset.disabled = false;

    if (state.status !== previousStatus || action === 'reset') {
      const messages = {
        idle: `${petName}陪你一起专注！准备好就点击“开始”。`,
        running: `${petName}陪你探索太空，专心做好眼前的事！`,
        paused: `${petName}帮你保留了进度，点击“开始”继续。`,
        completed: `${petName}为你鼓掌！任务完成，点击“重置”再玩一轮。`
      };
      encouragement.textContent = messages[state.status] || messages.idle;
      previousStatus = state.status;
    }

    const announcements = {
      start: '任务已开始，倒计时进行中。',
      pause: '任务已暂停，剩余时间已保留。',
      reset: '已重置，恢复初始时长并停止。点击“开始”重新出发。',
      complete: '任务完成！点击“重置”可以再玩一轮。'
    };
    if (Object.prototype.hasOwnProperty.call(announcements, action)) {
      announcement.textContent = announcements[action];
    }
  }

  window.addEventListener('sprout:timer-update', (event) => {
    if (event.detail) update(event.detail, event.detail.action);
  });
  update(window.SPROUT_TIMER.getState(), 'init');
})();
